// ============================================================
// 1. OBTENER LA RESPUESTA DE OLLAMA
// ============================================================

const rawContent =
  $json.content ??
  $json.message?.content ??
  $json.response ??
  $json.output ??
  '';

if (
  rawContent === null ||
  rawContent === undefined ||
  (
    typeof rawContent === 'string' &&
    !rawContent.trim()
  )
) {
  throw new Error(
    'No se encontró contenido válido en la respuesta de Ollama.'
  );
}


// ============================================================
// 2. FUNCIONES PARA RECUPERAR Y REPARAR EL JSON
// ============================================================

// Extrae el primer objeto o array JSON completo.
// Permite ignorar textos como:
// "Aquí tienes el resultado: { ... }"
const extractFirstJsonStructure = (text) => {
  const objectPosition = text.indexOf('{');
  const arrayPosition = text.indexOf('[');

  const possibleStarts = [
    objectPosition,
    arrayPosition,
  ].filter((position) => position >= 0);

  if (possibleStarts.length === 0) {
    return text.trim();
  }

  const startPosition = Math.min(...possibleStarts);

  const stack = [];
  let insideString = false;
  let escaped = false;

  for (
    let index = startPosition;
    index < text.length;
    index++
  ) {
    const character = text[index];

    if (insideString) {
      if (escaped) {
        escaped = false;
        continue;
      }

      if (character === '\\') {
        escaped = true;
        continue;
      }

      if (character === '"') {
        insideString = false;
      }

      continue;
    }

    if (character === '"') {
      insideString = true;
      continue;
    }

    if (
      character === '{' ||
      character === '['
    ) {
      stack.push(character);
      continue;
    }

    if (
      character === '}' ||
      character === ']'
    ) {
      const expectedOpening =
        character === '}' ? '{' : '[';

      const lastOpening =
        stack[stack.length - 1];

      if (lastOpening !== expectedOpening) {
        continue;
      }

      stack.pop();

      if (stack.length === 0) {
        return text
          .slice(startPosition, index + 1)
          .trim();
      }
    }
  }

  // Si no encuentra un cierre completo,
  // devuelve desde el primer inicio de JSON.
  return text.slice(startPosition).trim();
};


// Elimina Markdown, caracteres invisibles y texto externo.
const prepareJsonText = (value) => {
  let text = String(value)
    // Elimina BOM.
    .replace(/^\uFEFF/, '')

    // Elimina caracteres invisibles frecuentes.
    .replace(/[\u200B-\u200D\u2060]/g, '')

    // Normaliza comillas dobles tipográficas.
    .replace(/[“”]/g, '"')

    .trim();

  // Elimina bloques Markdown.
  text = text
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  return extractFirstJsonStructure(text);
};


// Devuelve el último carácter no vacío ya generado.
const getPreviousSignificantCharacter = (text) => {
  for (
    let index = text.length - 1;
    index >= 0;
    index--
  ) {
    if (!/\s/.test(text[index])) {
      return text[index];
    }
  }

  return '';
};


// Corrige errores estructurales frecuentes de los modelos:
// - "Elemento"
// * "Elemento"
// + "Elemento"
// Comas finales: ["a", "b",]
// Saltos de línea sin escapar dentro de textos.
const repairJsonStructure = (text) => {
  let repairedText = '';
  let insideString = false;
  let escaped = false;

  for (
    let index = 0;
    index < text.length;
    index++
  ) {
    const character = text[index];

    if (insideString) {
      if (escaped) {
        repairedText += character;
        escaped = false;
        continue;
      }

      if (character === '\\') {
        repairedText += character;
        escaped = true;
        continue;
      }

      if (character === '"') {
        repairedText += character;
        insideString = false;
        continue;
      }

      // Los saltos de línea literales no son válidos
      // dentro de strings JSON.
      if (
        character === '\n' ||
        character === '\r' ||
        character === '\t'
      ) {
        repairedText += ' ';
        continue;
      }

      repairedText += character;
      continue;
    }

    if (character === '"') {
      repairedText += character;
      insideString = true;
      continue;
    }

    // Corrige listas Markdown introducidas dentro de arrays.
    if (
      character === '-' ||
      character === '*' ||
      character === '+'
    ) {
      const previousCharacter =
        getPreviousSignificantCharacter(repairedText);

      let nextIndex = index + 1;

      while (
        nextIndex < text.length &&
        /\s/.test(text[nextIndex])
      ) {
        nextIndex++;
      }

      const nextCharacter = text[nextIndex];

      const isStructuralBullet =
        (
          previousCharacter === '[' ||
          previousCharacter === ',' ||
          previousCharacter === '{'
        ) &&
        (
          nextCharacter === '"' ||
          nextCharacter === '{' ||
          nextCharacter === '['
        );

      if (isStructuralBullet) {
        // Omite el símbolo -, * o +.
        // También avanza hasta el siguiente valor real.
        index = nextIndex - 1;
        continue;
      }
    }

    // Elimina comas finales antes de } o ].
    if (character === ',') {
      let nextIndex = index + 1;

      while (
        nextIndex < text.length &&
        /\s/.test(text[nextIndex])
      ) {
        nextIndex++;
      }

      const nextCharacter = text[nextIndex];

      if (
        nextCharacter === '}' ||
        nextCharacter === ']'
      ) {
        continue;
      }
    }

    repairedText += character;
  }

  return repairedText.trim();
};


// Convierte literales habituales de Python/JavaScript
// a valores válidos de JSON.
// Solo actúa fuera de strings.
const repairBareLiterals = (text) => {
  const replacements = {
    True: 'true',
    False: 'false',
    None: 'null',
    undefined: 'null',
    NaN: 'null',
  };

  let repairedText = '';
  let insideString = false;
  let escaped = false;

  for (
    let index = 0;
    index < text.length;
    index++
  ) {
    const character = text[index];

    if (insideString) {
      repairedText += character;

      if (escaped) {
        escaped = false;
        continue;
      }

      if (character === '\\') {
        escaped = true;
        continue;
      }

      if (character === '"') {
        insideString = false;
      }

      continue;
    }

    if (character === '"') {
      repairedText += character;
      insideString = true;
      continue;
    }

    if (/[A-Za-z]/.test(character)) {
      let endIndex = index;

      while (
        endIndex < text.length &&
        /[A-Za-z]/.test(text[endIndex])
      ) {
        endIndex++;
      }

      const word = text.slice(index, endIndex);

      repairedText +=
        replacements[word] ?? word;

      index = endIndex - 1;
      continue;
    }

    repairedText += character;
  }

  return repairedText;
};


// Limita el contenido mostrado en los errores,
// para evitar respuestas excesivamente grandes.
const getErrorPreview = (
  value,
  maximumLength = 7000
) => {
  const text = String(value);

  if (text.length <= maximumLength) {
    return text;
  }

  return `${text.slice(0, maximumLength)}... [contenido recortado]`;
};


// ============================================================
// 3. INTERPRETAR EL JSON
// ============================================================

let analysis;
let cleanedContent = '';
let repairedContent = '';

// Algunas integraciones pueden devolver el objeto directamente.
if (
  typeof rawContent === 'object' &&
  rawContent !== null &&
  !Array.isArray(rawContent)
) {
  analysis = rawContent;
} else {
  cleanedContent = prepareJsonText(rawContent);

  try {
    // Primer intento: JSON exacto, sin modificarlo.
    analysis = JSON.parse(cleanedContent);
  } catch (originalError) {
    // Segundo intento: reparar errores frecuentes.
    repairedContent = repairBareLiterals(
      repairJsonStructure(cleanedContent)
    );

    try {
      analysis = JSON.parse(repairedContent);
    } catch (repairedError) {
      throw new Error(
        [
          'Ollama no devolvió JSON válido.',
          `Error original: ${originalError.message}.`,
          `Error después de intentar repararlo: ${repairedError.message}.`,
          '',
          'Contenido reparado recibido:',
          getErrorPreview(repairedContent),
        ].join(' ')
      );
    }
  }
}

if (
  typeof analysis !== 'object' ||
  analysis === null ||
  Array.isArray(analysis)
) {
  throw new Error(
    'La respuesta de Ollama debe ser un objeto JSON.'
  );
}


// ============================================================
// 4. FUNCIONES DE NORMALIZACIÓN
// ============================================================

// Limpia un texto:
// - Elimina saltos de línea.
// - Elimina tabulaciones.
// - Reduce espacios repetidos.
// - Quita espacios iniciales y finales.
const cleanString = (value, fallback = '') => {
  if (
    value === null ||
    value === undefined
  ) {
    return fallback;
  }

  return String(value)
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};


// Normaliza un número dentro de unos límites.
const cleanNumber = (
  value,
  min = 0,
  max = 100
) => {
  let normalizedValue = value;

  // Permite valores como:
  // "35"
  // "35 puntos"
  // "35/40"
  // "35,5"
  if (typeof value === 'string') {
    const numberMatch = value
      .replace(',', '.')
      .match(/-?\d+(?:\.\d+)?/);

    normalizedValue =
      numberMatch?.[0] ?? value;
  }

  const number = Number(normalizedValue);

  if (!Number.isFinite(number)) {
    return min;
  }

  return Math.min(
    max,
    Math.max(min, Math.round(number))
  );
};


// Normaliza valores booleanos.
const cleanBoolean = (
  value,
  fallback = true
) => {
  if (typeof value === 'boolean') {
    return value;
  }

  if (typeof value === 'number') {
    if (value === 1) {
      return true;
    }

    if (value === 0) {
      return false;
    }
  }

  if (typeof value === 'string') {
    const normalizedValue = value
      .trim()
      .toLowerCase();

    if (
      normalizedValue === 'true' ||
      normalizedValue === 'sí' ||
      normalizedValue === 'si' ||
      normalizedValue === '1'
    ) {
      return true;
    }

    if (
      normalizedValue === 'false' ||
      normalizedValue === 'no' ||
      normalizedValue === '0'
    ) {
      return false;
    }
  }

  return fallback;
};


// Limpia los elementos de un array.
const cleanArray = (value) => {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((item) => {
      if (
        typeof item === 'object' &&
        item !== null
      ) {
        return cleanString(
          item.nombre ??
          item.valor ??
          item.texto ??
          item.descripcion ??
          ''
        );
      }

      return cleanString(item);
    })
    .filter(Boolean);
};


// Convierte un array en frases separadas por puntos.
const arrayToText = (value) => {
  const items = cleanArray(value);

  if (items.length === 0) {
    return '';
  }

  const normalizedItems = items.map((item) =>
    item
      .replace(/[.;,\s]+$/g, '')
      .trim()
  );

  return `${normalizedItems.join('. ')}.`;
};


// Convierte un array en texto separado por comas.
const arrayToCommaText = (value) => {
  return cleanArray(value).join(', ');
};


// ============================================================
// 5. NORMALIZAR PUNTUACIONES
// ============================================================

const puntuacionTecnica = cleanNumber(
  analysis.puntuacion_tecnica,
  0,
  40
);

const puntuacionExperiencia = cleanNumber(
  analysis.puntuacion_experiencia,
  0,
  25
);

const puntuacionFormacion = cleanNumber(
  analysis.puntuacion_formacion,
  0,
  15
);

const puntuacionProyectos = cleanNumber(
  analysis.puntuacion_proyectos,
  0,
  10
);

const puntuacionComplementaria = cleanNumber(
  analysis.puntuacion_complementaria,
  0,
  10
);


// Calcula la puntuación total para evitar
// inconsistencias producidas por la IA.
const puntuacionCalculada =
  puntuacionTecnica +
  puntuacionExperiencia +
  puntuacionFormacion +
  puntuacionProyectos +
  puntuacionComplementaria;


// ============================================================
// 6. NORMALIZAR NIVEL DE AJUSTE
// ============================================================

let nivelAjuste = cleanString(
  analysis.nivel_ajuste
);

const nivelAjusteNormalizado =
  nivelAjuste.toLowerCase();

if (nivelAjusteNormalizado === 'alto') {
  nivelAjuste = 'Alto';
} else if (nivelAjusteNormalizado === 'medio') {
  nivelAjuste = 'Medio';
} else if (nivelAjusteNormalizado === 'bajo') {
  nivelAjuste = 'Bajo';
} else if (puntuacionCalculada >= 75) {
  nivelAjuste = 'Alto';
} else if (puntuacionCalculada >= 50) {
  nivelAjuste = 'Medio';
} else {
  nivelAjuste = 'Bajo';
}


// ============================================================
// 7. NORMALIZAR RECOMENDACIÓN
// ============================================================

let recomendacion = cleanString(
  analysis.recomendacion
);

const recomendacionNormalizada =
  recomendacion.toLowerCase();

if (
  recomendacionNormalizada ===
  'revisión prioritaria'
) {
  recomendacion = 'Revisión prioritaria';
} else if (
  recomendacionNormalizada ===
  'revisión estándar'
) {
  recomendacion = 'Revisión estándar';
} else if (
  recomendacionNormalizada ===
  'requiere más información'
) {
  recomendacion = 'Requiere más información';
} else if (puntuacionCalculada >= 75) {
  recomendacion = 'Revisión prioritaria';
} else if (puntuacionCalculada >= 50) {
  recomendacion = 'Revisión estándar';
} else {
  recomendacion = 'Requiere más información';
}


// ============================================================
// 8. NORMALIZAR IDIOMAS
// ============================================================

const idiomas = Array.isArray(analysis.idiomas)
  ? analysis.idiomas
      .map((idioma) => {
        // Permite idiomas como objeto:
        // { "idioma": "Inglés", "nivel": "A1" }
        if (
          typeof idioma === 'object' &&
          idioma !== null
        ) {
          return {
            idioma: cleanString(
              idioma.idioma ??
              idioma.nombre
            ),
            nivel: cleanString(
              idioma.nivel,
              'No especificado'
            ),
          };
        }

        // También acepta un string simple.
        return {
          idioma: cleanString(idioma),
          nivel: 'No especificado',
        };
      })
      .filter((idioma) => idioma.idioma)
  : [];


// Idiomas sin saltos de línea.
const idiomasTexto = idiomas
  .map(
    (item) =>
      `${item.idioma}: ${item.nivel}`
  )
  .join(' | ');


// ============================================================
// 9. OBJETO FINAL PARA GOOGLE SHEETS,
//    POWER AUTOMATE O SHAREPOINT
// ============================================================

const result = {
  procesado_correctamente: true,

  resumen_profesional: cleanString(
    analysis.resumen_profesional
  ),

  puntuacion_total: puntuacionCalculada,
  puntuacion_tecnica: puntuacionTecnica,
  puntuacion_experiencia:
    puntuacionExperiencia,
  puntuacion_formacion:
    puntuacionFormacion,
  puntuacion_proyectos:
    puntuacionProyectos,
  puntuacion_complementaria:
    puntuacionComplementaria,

  nivel_ajuste: nivelAjuste,
  recomendacion,

  justificacion_recomendacion: cleanString(
    analysis.justificacion_recomendacion
  ),

  anos_experiencia_confirmados: cleanNumber(
    analysis.anos_experiencia_confirmados,
    0,
    50
  ),

  experiencia_relevante: cleanString(
    analysis.experiencia_relevante
  ),

  habilidades_confirmadas: arrayToCommaText(
    analysis.habilidades_confirmadas
  ),

  herramientas_automatizacion:
    arrayToCommaText(
      analysis.herramientas_automatizacion
    ),

  lenguajes_programacion: arrayToCommaText(
    analysis.lenguajes_programacion
  ),

  infraestructura_y_sistemas:
    arrayToCommaText(
      analysis.infraestructura_y_sistemas
    ),

  formacion_relevante: arrayToText(
    analysis.formacion_relevante
  ),

  idiomas: idiomasTexto,

  requisitos_cumplidos: arrayToText(
    analysis.requisitos_cumplidos
  ),

  requisitos_no_especificados: arrayToText(
    analysis.requisitos_no_especificados
  ),

  aspectos_destacados: arrayToText(
    analysis.aspectos_destacados
  ),

  aspectos_a_verificar: arrayToText(
    analysis.aspectos_a_verificar
  ),

  preguntas_entrevista: arrayToText(
    analysis.preguntas_entrevista
  ),

  requiere_revision_humana: cleanBoolean(
    analysis.requiere_revision_humana,
    true
  ),

  // Copia estructurada para usos posteriores.
  detalle_json: JSON.stringify({
    habilidades_confirmadas: cleanArray(
      analysis.habilidades_confirmadas
    ),

    herramientas_automatizacion: cleanArray(
      analysis.herramientas_automatizacion
    ),

    lenguajes_programacion: cleanArray(
      analysis.lenguajes_programacion
    ),

    infraestructura_y_sistemas: cleanArray(
      analysis.infraestructura_y_sistemas
    ),

    formacion_relevante: cleanArray(
      analysis.formacion_relevante
    ),

    idiomas,

    requisitos_cumplidos: cleanArray(
      analysis.requisitos_cumplidos
    ),

    requisitos_no_especificados: cleanArray(
      analysis.requisitos_no_especificados
    ),

    aspectos_destacados: cleanArray(
      analysis.aspectos_destacados
    ),

    aspectos_a_verificar: cleanArray(
      analysis.aspectos_a_verificar
    ),

    preguntas_entrevista: cleanArray(
      analysis.preguntas_entrevista
    ),
  }),
};


return [
  {
    json: result,
  },
];

